<form class="panel" method="post" action="/admin/listings/save" enctype="multipart/form-data" style="max-width:820px"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($l['id'] ?? '') ?>"><div class="panel-b form">
<div class="row2"><?= a_in('Title', 'title', $l['title'] ?? '', ['required' => true]) ?><?= a_sel('Service area', 'service', array_merge(['' => 'Select…'], array_map(fn($s) => $s['title'], $services)), $l['service'] ?? '') ?></div>
<div class="row3"><?= a_sel('Type', 'type', ['project' => 'Project / example', 'product' => 'Product', 'property' => 'Property', 'package' => 'Package'], $l['type'] ?? 'project') ?><?= a_in('Price', 'price', $l['price'] ?? '', ['ph' => 'e.g. KSh 25,000']) ?><?= a_in('Location', 'location', $l['location'] ?? '') ?></div>
<?= a_in('Description', 'description', $l['description'] ?? '', ['type' => 'textarea']) ?>
<div class="row2"><div class="field"><label for="f-image">Image</label><input id="f-image" type="file" name="image" accept="image/*"><?php if (!empty($l['image'])): ?><span class="hint">Current: <?= e($l['image']) ?></span><?php endif; ?></div><?= a_in('Video link (YouTube/Vimeo)', 'video', $l['video'] ?? '') ?></div>
<?= a_sel('Visibility', 'status', ['Active' => 'Visible on the website', 'Hidden' => 'Hidden'], $l['status'] ?? 'Active') ?><div><button class="btn btn-primary">Save listing</button> <a class="btn btn-ghost" href="/admin/listings">Cancel</a></div></div></form>
